// ─── Parse & filtre les recyclages pertinents ─────────────────────
const raw = $input.item.json?.content?.[0]?.text || '{}';
let recycling;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  recycling = JSON.parse(match ? match[0] : raw);
} catch(e) {
  return [{ json: { _skip: true, reason: 'JSON parse error: ' + raw.substring(0,100) } }];
}

const prospect = $('Fetch prospects froids ≥90j (DB)').item.json;

// Ne recycler que si confiance medium ou high et nouveau score >= 5
if (recycling.confidence === 'low' || (recycling.new_score || 0) < 5) {
  return [{ json: { _skip: true, reason: `Confiance ${recycling.confidence} ou score trop bas (${recycling.new_score})` } }];
}

// Date de relance : étaler sur 2 semaines avec jitter
const daysDelay = Math.floor(Math.random() * 10) + 1; // 1 à 10 jours
const scheduledFor = new Date(Date.now() + daysDelay * 24 * 3600 * 1000).toISOString();

return [{
  json: {
    prospect_id: prospect.id,
    full_name: prospect.full_name,
    platform: prospect.platform,
    new_score: recycling.new_score || prospect.profile_score,
    new_angle: recycling.recycling_angle || '',
    new_public_fact: recycling.new_public_fact || '',
    message: recycling.message || '',
    confidence: recycling.confidence,
    reason: recycling.reason_to_contact_now || '',
    scheduled_for: scheduledFor,
    days_delay: daysDelay,
    insert_sql: `
      INSERT INTO cold_recycling
        (prospect_id, scheduled_for, reason_for_cold, new_score, new_angle,
         new_public_fact, recycling_prompt, status)
      VALUES
        (${prospect.id}, '${scheduledFor}',
         '${(prospect.cold_since || '').substring(0,100).replace(/'/g,"''")}',
         ${recycling.new_score || prospect.profile_score},
         '${(recycling.recycling_angle || '').replace(/'/g,"''")}',
         '${(recycling.new_public_fact || '').replace(/'/g,"''")}',
         '${(recycling.message || '').replace(/'/g,"''")}',
         'scheduled')
      ON CONFLICT (prospect_id) DO UPDATE
      SET scheduled_for = EXCLUDED.scheduled_for,
          new_score = EXCLUDED.new_score,
          new_angle = EXCLUDED.new_angle,
          status = 'scheduled'`,
    update_sql: `
      UPDATE prospects
      SET best_angle = '${(recycling.recycling_angle || '').replace(/'/g,"''")}',
          public_fact = '${(recycling.new_public_fact || '').replace(/'/g,"''")}',
          profile_score = ${recycling.new_score || prospect.profile_score}
      WHERE id = ${prospect.id}`
  }
}];

// ─── Rapport de recyclage hebdomadaire Discord ────────────────────
const items = $input.all().map(i => i.json).filter(i => !i._skip);
if (items.length === 0) return [];

const list = items.slice(0,5)
  .map(i => `• **${i.full_name}** — Nouveau score ${i.new_score}/10, relance dans ${i.days_delay}j`)
  .join('\n');

return [{
  json: {
    embeds: [{
      title: '♻️ Recyclage prospects froids — Rapport hebdomadaire',
      description: `**${items.length}** prospect(s) froid(s) re-qualifiés et programmés pour une relance avec un angle complètement nouveau.`,
      color: 9699539,
      fields: [
        { name: '📋 Prospects recyclés', value: list, inline: false },
        { name: '📅 Envois échelonnés sur', value: '10 jours maximum', inline: true },
        { name: '🤖 Re-qualification par', value: 'Claude Haiku (Prompt H)', inline: true }
      ],
      footer: { text: `Cold Recycling WF10 • ${new Date().toLocaleDateString('fr-FR')}` },
      timestamp: new Date().toISOString()
    }]
  }
}];
